function Movies({ movies = [], onSelectMovie }) {
  console.log("Movies props:", movies);

  return (
    <div className="row">
      {movies.length ? (
        movies.map((movie, index) => {
          console.log("Rendering movie:", movie);
          return (
            <div className="col s12 m6 l4" key={movie.imdbID || index}>
              <pre>{JSON.stringify(movie, null, 2)}</pre> {/* 👈 временный вывод */}
            </div>
          );
        })
      ) : (
        <div className="center-align" style={{ marginTop: "50px" }}>
          <h5>Ничего не найдено</h5>
        </div>
      )}
    </div>
  );
}
